def nodes_of(values):
    nodes = [ListNode(v) for v in values]
    for before, after in zip(nodes, nodes[1:]):
        before.next = after
    return nodes
def answer_for(values):
    nodes = nodes_of(values)
    return is_palindrome(nodes[0] if nodes else None)
def list_after(values):
    # run the function, then read the list again from its original head
    nodes = nodes_of(values)
    is_palindrome(nodes[0] if nodes else None)
    out, node = [], (nodes[0] if nodes else None)
    while node is not None and len(out) <= len(values):
        out.append(node.val)
        node = node.next
    return out
